// Type unique — noms et intervalles identiques pour les trois axes.
// Un PNJ a trois INSTANCES indépendantes de ce type (une par axe).
type RepPalier =
  | "Effondrement" // ≤ -100
  | "Rupture"      // -99 à -60
  | "Fragilité"    // -59 à -30
  | "Retrait"      // -29 à -10
  | "Neutre"      // -9 à +9
  | "Émergence"   // +10 à +29
  | "Ancrage"     // +30 à +59
  | "Ascendant"   // +60 à +99
  | "Paroxysme"   // ≥ +100

// Calculé à la volée pour une valeur brute donnée — appelé UNE FOIS PAR AXE
function palier(valeurBrute: number): RepPalier {
  if (valeurBrute <= -100) return "Effondrement"
  if (valeurBrute <= -60)  return "Rupture"
  if (valeurBrute <= -30)  return "Fragilité"
  if (valeurBrute <= -10)  return "Retrait"
  if (valeurBrute <= +9)   return "Neutre"
  if (valeurBrute <= +29)  return "Émergence"
  if (valeurBrute <= +59)  return "Ancrage"
  if (valeurBrute <= +99)  return "Ascendant"
  return "Paroxysme"
}

// État complet d'un PNJ vis-à-vis d'une héroïne :
// trois paliers indépendants, même type, interprétations comportementales distinctes
type EtatRepNPC = {
  admiration: RepPalier  // interprétation : "Apprécié·e", "Figure aimée"…
  prestige:   RepPalier  // interprétation : "Fiable", "Référence"…
  crainte:    RepPalier  // interprétation : "Intimidant·e", "Autorité de fait"…
}

function calculerEtat(rep: { admiration: number; prestige: number; crainte: number }): EtatRepNPC {
  return {
    admiration: palier(rep.admiration),
    prestige:   palier(rep.prestige),
    crainte:    palier(rep.crainte),
  }
}

// Seuils de maintien — utilisés pour la révocation de rôle
const MAINTIEN: Partial<Record<RepPalier, number>> = {
  Émergence: 0,
  Ancrage:   10,
  Ascendant: 30,
  Paroxysme: 60,
}
